'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'
import { attachGpuGate, deferUntilVisible } from '@/lib/gpu-runtime'
import { logger } from '@/utils/logger'
import { HEAT_SHADE_WGSL } from './heat-shade.wgsl'
import { HEAT_LICKS_WGSL } from './heat-licks.wgsl'

export type HeatShadeVariant = 'field' | 'licks'

export type HeatShadeFrom = 'top' | 'bottom'

export type HeatShadeProps = {
  base?: string
  hot?: string
  speed?: number
  variant?: HeatShadeVariant
  from?: HeatShadeFrom
  dpr?: number
  fps?: number
  rootMargin?: string
  className?: string
}

function hexToRgba(hex: string): [number, number, number, number] {
  const h = hex.replace('#', '')
  return [parseInt(h.slice(0, 2), 16) / 255, parseInt(h.slice(2, 4), 16) / 255, parseInt(h.slice(4, 6), 16) / 255, 1]
}

export function HeatShade({
  base = '#2a7bba',
  hot = '#43c8ff',
  speed = 1,
  variant = 'licks',
  from = 'bottom',
  dpr,
  fps,
  rootMargin = '80px',
  className,
}: HeatShadeProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const propsRef = React.useRef({ base, hot, speed, from })
  propsRef.current = { base, hot, speed, from }

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    let cancelled = false
    let stopLoop: (() => void) | undefined
    let disposeGpu: (() => void) | undefined
    let disposeGate: (() => void) | undefined
    let disposeDefer: (() => void) | undefined

    async function mount() {
      const { init, effect, surface, clock, frameLoop } = await import('vgpu')
      if (cancelled || !canvasRef.current) return
      if (!('gpu' in navigator)) return
      const gpu = await init()
      if (cancelled) {
        gpu.dispose()
        return
      }

      let running: { stop: () => void } | undefined
      let draw = (_passFrame: { pass: (target: unknown, fx: unknown) => void }) => {}

      const gate = attachGpuGate(canvas, (paused) => {
        if (paused) {
          running?.stop()
          running = undefined
        } else if (!running) {
          running = frameLoop(gpu, (frame) => draw(frame))
        }
      })
      disposeGate = gate.dispose
      const pixelRatio = dpr ?? (gate.state.lowPower ? 0.4 : Math.min(window.devicePixelRatio || 1, 1.25))
      const frameMs = fps ? 1000 / fps : gate.frameMs
      const canvasSurface = surface(gpu, canvasRef.current, {
        dpr: pixelRatio,
        alphaMode: 'premultiplied',
        format: 'bgra8unorm',
      })
      const p = propsRef.current
      const shade = effect(gpu, variant === 'licks' ? HEAT_LICKS_WGSL : HEAT_SHADE_WGSL, {
        set: {
          params: {
            resolution: [1, 1],
            time: 0,
            speed: p.speed,
            baseColor: hexToRgba(p.base),
            hotColor: hexToRgba(p.hot),
            fromTop: p.from === 'top' ? 1 : 0,
          },
        },
      })

      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
      let lastW = 0
      let lastH = 0
      let lastKey = ''
      let lastDraw = 0

      draw = (passFrame) => {
        if (gate.state.paused) return
        const now = performance.now()
        if (frameMs && now - lastDraw < frameMs) return
        lastDraw = now
        const width = Math.max(canvas.clientWidth, 1)
        const height = Math.max(canvas.clientHeight, 1)
        const cur = propsRef.current
        const next: Record<string, unknown> = {
          time: reduced ? 0 : clock(gpu).time,
          speed: cur.speed,
        }
        const key = `${cur.base}${cur.hot}${cur.speed}${cur.from}`
        if (key !== lastKey) {
          lastKey = key
          next.baseColor = hexToRgba(cur.base)
          next.hotColor = hexToRgba(cur.hot)
          next.fromTop = cur.from === 'top' ? 1 : 0
        }
        if (width !== lastW || height !== lastH) {
          lastW = width
          lastH = height
          next.resolution = [width, height]
        }
        shade.set({ params: next })
        passFrame.pass(canvasSurface, shade)
      }

      if (!gate.state.paused && !running) {
        running = frameLoop(gpu, (frame) => draw(frame))
      }
      stopLoop = () => {
        running?.stop()
        running = undefined
      }

      disposeGpu = () => {
        gpu.dispose()
      }
    }

    disposeDefer = deferUntilVisible(
      canvas,
      () => {
        mount().catch((error) => {
          logger.error('HeatShade WebGPU init failed:', error)
        })
      },
      rootMargin,
    )

    return () => {
      cancelled = true
      disposeDefer?.()
      stopLoop?.()
      disposeGate?.()
      disposeGpu?.()
    }
  }, [variant, dpr, fps, rootMargin])

  return <canvas ref={canvasRef} aria-label="Animated heat shade" className={cn('block size-full', className)} />
}

export const HEAT_SHADE_WGSL = /* wgsl */ `
struct Params {
  resolution: vec2f,
  time: f32,
  speed: f32,
  baseColor: vec4f,
  hotColor: vec4f,
  fromTop: f32,
  _pad0: f32,
  _pad1: f32,
  _pad2: f32,
}

@group(0) @binding(0) var<uniform> params: Params;

fn hash(point: vec2f) -> f32 {
  return fract(sin(dot(point, vec2f(127.1, 311.7))) * 43758.5453);
}

fn noise(point: vec2f) -> f32 {
  let cell = floor(point);
  let local = fract(point);
  let blend = local * local * (3.0 - 2.0 * local);
  let bottom = mix(hash(cell), hash(cell + vec2f(1.0, 0.0)), blend.x);
  let top = mix(
    hash(cell + vec2f(0.0, 1.0)),
    hash(cell + vec2f(1.0, 1.0)),
    blend.x
  );
  return mix(bottom, top, blend.y);
}

fn fbm(point: vec2f) -> f32 {
  var position = point;
  var value = 0.0;
  var amplitude = 0.5;
  for (var octave = 0; octave < 4; octave += 1) {
    value += noise(position) * amplitude;
    position = position * 2.03 + vec2f(7.1, 3.7);
    amplitude *= 0.5;
  }
  return value;
}

@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let y = mix(uv.y, 1.0 - uv.y, params.fromTop);
  let aspect = params.resolution.x / max(params.resolution.y, 1.0);
  let motion = params.time * params.speed;
  let wideNoise = fbm(vec2f(uv.x * aspect * 1.45, -motion * 0.15));
  let warp = fbm(vec2f(uv.x * aspect * 2.4 + wideNoise, y * 1.7 - motion * 0.23));
  let detail = fbm(vec2f(uv.x * aspect * 5.2 + warp * 1.3, -motion * 0.36));
  let slowWave = sin(uv.x * aspect * 4.2 + motion * 0.17) * 0.035;
  let boundary = 0.61 - wideNoise * 0.24 - warp * 0.14
    + detail * 0.08 + slowWave;
  let signedDistance = y - boundary;
  let primaryFlame = smoothstep(-0.045, 0.075, signedDistance);

  let secondaryNoise = fbm(vec2f(
    uv.x * aspect * 1.8 + 4.7,
    -motion * 0.21
  ));
  let secondaryWarp = fbm(vec2f(
    uv.x * aspect * 3.1 + secondaryNoise * 1.2,
    y * 1.9 - motion * 0.31
  ));
  let secondaryBoundary = 0.68 - secondaryNoise * 0.2
    - secondaryWarp * 0.11
    + sin(uv.x * aspect * 5.4 - motion * 0.24) * 0.025;
  let secondaryDistance = y - secondaryBoundary;
  let secondaryFlame = smoothstep(-0.035, 0.065, secondaryDistance);
  let flame = max(primaryFlame, secondaryFlame * 0.88);
  let softEdge = exp(-abs(signedDistance) * 18.0);
  let secondaryEdge = exp(-abs(secondaryDistance) * 21.0);
  let verticalHeat = smoothstep(boundary - 0.02, 1.0, y);
  let grain = noise(vec2f(uv.x, y) * params.resolution * 0.18 + motion * 1.1) - 0.5;

  let ember = params.baseColor.xyz;
  var color = mix(vec3f(0.0), ember, flame);
  color = mix(
    color,
    params.baseColor.xyz,
    flame * (0.42 + verticalHeat * 0.4)
  );
  color += params.hotColor.xyz * softEdge * 0.38;
  color += mix(params.baseColor.xyz, params.hotColor.xyz, 0.65)
    * secondaryEdge * 0.22;
  color += params.hotColor.xyz * grain * flame * 0.016;

  let alpha = clamp(flame * 0.82 + softEdge * 0.22, 0.0, 1.0);
  return vec4f(color * alpha, alpha);
}
`

export const HEAT_LICKS_WGSL = /* wgsl */ `
struct Params {
  resolution: vec2f,
  time: f32,
  speed: f32,
  baseColor: vec4f,
  hotColor: vec4f,
  fromTop: f32,
  _pad0: f32,
  _pad1: f32,
  _pad2: f32,
}

@group(0) @binding(0) var<uniform> params: Params;

fn hash(point: vec2f) -> f32 {
  return fract(sin(dot(point, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn noise(point: vec2f) -> f32 {
  let cell = floor(point);
  let local = fract(point);
  let blend = local * local * (3.0 - 2.0 * local);
  return mix(
    mix(hash(cell), hash(cell + vec2f(1.0, 0.0)), blend.x),
    mix(hash(cell + vec2f(0.0, 1.0)), hash(cell + vec2f(1.0, 1.0)), blend.x),
    blend.y
  );
}

fn fbm(point: vec2f) -> f32 {
  var position = point;
  var value = 0.0;
  var amplitude = 0.6;
  for (var octave = 0; octave < 3; octave += 1) {
    value += amplitude * noise(position);
    position *= 2.0;
    amplitude *= 0.5;
  }
  return value;
}

@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let y = mix(1.0 - uv.y, uv.y, params.fromTop);
  let motion = params.time * params.speed * 0.18;
  let x = uv.x + 0.05 * sin(y * 3.2 + motion * 0.6);
  let a = fbm(vec2f(x * 2.6, y * 1.6 - motion));
  let b = fbm(vec2f(x * 5.3 + 4.2, y * 2.9 - motion * 1.5));
  let field = a * 0.72 + b * 0.34;
  let energy = clamp(field * 2.4 - y * 2.3, 0.0, 1.0);
  let alpha = 0.3 * smoothstep(0.06, 0.5, energy) + 0.7 * smoothstep(0.5, 0.96, energy);
  let color = mix(params.baseColor.xyz, params.hotColor.xyz, energy);
  return vec4f(color * alpha, alpha);
}
`
